const alphabet='abcdefghijklmnopqrstuvwxyz'.split('');
function getCipherMap(shift){
  return alphabet.reduce((m,c,i)=>{
    let idx=((i+shift)%alphabet.length+alphabet.length)%alphabet.length;
    m[c]=alphabet[idx];
    return m;
  },{});
}
function enc(str,shift){return str.toLowerCase().split('').map(ch=>getCipherMap(shift)[ch]||ch).join('');}
function dec(str,shift){return str.toLowerCase().split('').map(ch=>getCipherMap(-shift)[ch]||ch).join('');}
console.log("enc 'abcde' 3 =>", enc('abcde',3), "(want defgh)");
console.log("dec 'defgh' 3 =>", dec('defgh',3), "(want abcde)");
